/** @param {NS} ns */
export async function main(ns) {
  const current = ns.getHostname();
  ns.tprint(`Current: ${current}`);

  const connected = ns.scan(current);
  ns.tprint(`scan: returned ${connected.length} connections`);
  ns.tprint(`Connected servers: ${connected.join(', ')}`);
  ns.tprint('');

  let bestTarget = null;
  let bestMoney = 0;

  for (const server of connected) {
    const maxMoney = ns.getServerMaxMoney(server);
    const curMoney = ns.getServerMoneyAvailable(server);
    const minSec = ns.getServerMinSecurityLevel(server);
    const curSec = ns.getServerSecurityLevel(server);
    const reqLevel = ns.getServerRequiredHackingLevel(server);
    const hasRoot = ns.hasRootAccess(server);

    let hackTime = 'N/A';
    let growTime = 'N/A';
    let weakenTime = 'N/A';

    try {
      hackTime = ns.getHackTime(server).toFixed(1) + 's';
      growTime = ns.getGrowTime(server).toFixed(1) + 's';
      weakenTime = ns.getWeakenTime(server).toFixed(1) + 's';
    } catch (e) {
      // Times not available
    }

    ns.tprint(`${server}:`);
    ns.tprint(`  Max Money: $${maxMoney} | Cur Money: $${curMoney}`);
    ns.tprint(`  Security: ${minSec.toFixed(3)} (min) / ${curSec.toFixed(3)} (cur)`);
    ns.tprint(`  Req Level: ${reqLevel} | Root: ${hasRoot}`);
    ns.tprint(`  Times: hack=${hackTime} grow=${growTime} weaken=${weakenTime}`);
    ns.tprint('');

    if (curMoney > 0 && hasRoot && curMoney > bestMoney) {
      bestMoney = curMoney;
      bestTarget = server;
    }
  }

  if (bestTarget) {
    ns.tprint(`BEST TARGET: ${bestTarget} ($${bestMoney})`);
  } else {
    ns.tprint('No suitable targets found (need money > 0 and root access)');
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const currentHost = ns.getHostname();
  const myHackLevel = ns.getHackingLevel();
  const toCheck = new Set([currentHost]);
  const visited = new Set();
  const servers = [];

  while (toCheck.size > 0) {
    const host = toCheck.values().next().value;
    toCheck.delete(host);
    if (visited.has(host)) continue;
    visited.add(host);

    const rooted = ns.hasRootAccess(host) ? 1 : 0;
    const req = ns.getServerRequiredHackingLevel(host);
    const max = ns.getServerMaxMoney(host);
    const cur = ns.getServerMoneyAvailable(host);
    const min = ns.getServerMinSecurityLevel(host);
    const sec = ns.getServerSecurityLevel(host);

    ns.tprint(`SERVER ${host} rooted=${rooted} req=${req} max=${max} cur=${cur} min=${min} sec=${sec}`);

    servers.push({ host, rooted, req, max });

    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) toCheck.add(neighbor);
    }
  }

  let best = null;
  let bestMax = -1;
  for (const s of servers) {
    if (s.rooted && s.req <= myHackLevel && s.max > bestMax) {
      best = s;
      bestMax = s.max;
    }
  }

  if (best) {
    ns.tprint(`BEST ${best.host} max=${best.max} rooted=${best.rooted} req=${best.req}`);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  let target = "";
  let first = true;

  while (true) {
    let hackLvl = ns.getHackingLevel();
    let candidates = [];

    // Gather current host and directly connected servers
    let queue = [ns.getHostname()];
    let visited = {};
    visited[ns.getHostname()] = true;

    while (queue.length > 0) {
      let host = queue.shift();
      let neighbors = ns.scan(host);
      for (let neighbor of neighbors) {
        if (!visited[neighbor]) {
          visited[neighbor] = true;
          queue.push(neighbor);

          // Check if rooted and valid
          if (ns.hasRootAccess(neighbor)) {
            let reqLvl = ns.getServerRequiredHackingLevel(neighbor);
            let maxMoney = ns.getServerMaxMoney(neighbor);
            if (reqLvl <= hackLvl && maxMoney > 0) {
              candidates.push({name: neighbor, maxMoney: maxMoney});
            }
          }
        }
      }
    }

    // Choose target
    if (candidates.length === 0) {
      await ns.sleep(100);
      continue;
    }

    let chosen = candidates[0];
    for (let c of candidates) {
      if (c.name === "n00dles") {
        chosen = c;
        break;
      }
    }
    if (chosen.name !== "n00dles") {
      for (let c of candidates) {
        if (c.name === "foodnstuff") {
          chosen = c;
          break;
        }
      }
    }
    if (chosen.name !== "n00dles" && chosen.name !== "foodnstuff") {
      for (let c of candidates) {
        if (c.maxMoney > chosen.maxMoney) chosen = c;
      }
    }

    if (first) {
      ns.print("Target: " + chosen.name);
      first = false;
    }
    target = chosen.name;

    // Act on target
    let security = ns.getServerSecurityLevel(target);
    let minSec = ns.getServerMinSecurityLevel(target);
    let money = ns.getServerMoneyAvailable(target);
    let maxMoney = ns.getServerMaxMoney(target);

    if (security > minSec + 2) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

