/** @param {NS} ns */
export async function main(ns) {
  const home = 'home';

  while (true) {
    const myLevel = ns.getHackingLevel();
    const servers = ns.scan(home);
    let bestTarget = null;
    let bestMoney = 0;

    for (const srv of servers) {
      if (!ns.hasRootAccess(srv)) continue;
      const reqLevel = ns.getServerRequiredHackingLevel(srv);
      if (reqLevel > myLevel) continue;
      const maxMoney = ns.getServerMaxMoney(srv);
      if (maxMoney <= 0) continue;
      if (maxMoney > bestMoney) {
        bestMoney = maxMoney;
        bestTarget = srv;
      }
    }

    if (bestTarget === null) {
      bestTarget = 'n00dles';
      if (!ns.hasRootAccess(bestTarget)) bestTarget = 'foodnstuff';
      if (!ns.hasRootAccess(bestTarget)) {
        await ns.sleep(1000);
        continue;
      }
    }

    const curMoney = ns.getServerMoneyAvailable(bestTarget);
    const maxMoney = ns.getServerMaxMoney(bestTarget);
    const curSec = ns.getServerSecurityLevel(bestTarget);
    const minSec = ns.getServerMinSecurityLevel(bestTarget);

    if (curMoney < maxMoney * 0.75) {
      await ns.grow(bestTarget);
    } else if (curSec > minSec + 2) {
      await ns.weaken(bestTarget);
    } else {
      await ns.hack(bestTarget);
    }

    await ns.sleep(100);
  }
}

